/**
 * Build-time access to the exam bank. The import manifest is regenerated by
 * npm's predev/prebuild hooks whenever /data/exams changes, so new JSON files
 * automatically become static routes. Never import this from a Client Component.
 */
import { examPapers } from "@/generated/exam-manifest";
import type { ExamPaper } from "@/types/exam";
import type { JlptLevel } from "@/types/japanese";
import { LEVELS } from "@/lib/site";

export const allExamPapers: readonly ExamPaper[] = examPapers;

export function getExamPaper(id: string): ExamPaper | undefined {
  return allExamPapers.find((paper) => paper.id === id);
}

export function examPapersForLevel(level: JlptLevel): ExamPaper[] {
  return allExamPapers.filter((paper) => paper.level === level);
}

export function examPapersByLevel(): Array<{
  level: JlptLevel;
  papers: ExamPaper[];
}> {
  return LEVELS.map((level) => ({
    level,
    papers: examPapersForLevel(level),
  })).filter((group) => group.papers.length > 0);
}
